import{_ as r,a0 as p,w as l,s,I as o,x as e,a1 as i,A as a,ao as m}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const S=JSON.parse('{"title":"如何在Linux中用命令行工具管理KVM虚拟环境 | LCTT x X-CMD","titleTemplate":false,"description":"如何在Linux中用命令行工具管理KVM虚拟环境 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Linux中用命令行工具管理KVM虚拟环境 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Linux中用命令行工具管理KVM虚拟环境 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150302 How to Manage KVM Virtual Environment using Commandline Tools in Linux","title":"如何在Linux中用命令行工具管理KVM虚拟环境","tag":"201505","desc":""},"relativePath":"201505/20150302 How to Manage KVM Virtual Environment using Commandline Tools in Linux.md","filePath":"[post].md"}'),d={name:"201505/20150302 How to Manage KVM Virtual Environment using Commandline Tools in Linux.md"};function u(g,t,c,h,w,v){const n=p("Link");return l(),s("div",null,[t[18]||(t[18]=o("h1",{id:"如何在linux中用命令行工具管理kvm虚拟环境",tabindex:"-1"},[e("如何在Linux中用命令行工具管理KVM虚拟环境 "),o("a",{class:"header-anchor",href:"#如何在linux中用命令行工具管理kvm虚拟环境","aria-label":"Permalink to “如何在Linux中用命令行工具管理KVM虚拟环境”"},"​")],-1)),o("p",null,[t[1]||(t[1]=e("在我们",-1)),i(n,{href:"http://www.tecmint.com/install-and-configure-kvm-in-linux/"},{default:a(()=>[...t[0]||(t[0]=[e("KVM系列专题",-1)])]),_:1}),t[2]||(t[2]=e("的第四部分，我们将会一起讨论下在命令行界面下来管理KVM环境。我们分别用‘virt-install’和virsh命令行工具来创建并配置虚拟机和存储池，用qemu-img命令行工具来创建并管理磁盘映像。",-1))]),t[19]||(t[19]=m(`<p><img src="http://www.tecmint.com/wp-content/uploads/2015/02/KVM-Management-in-Linux.jpg" alt="KVM Management in Linux"></p><p><em>Linux系统的KVM管理</em></p><p>在这篇文章里没有什么新的概念，我们只是用命令行工具重复之前所做过的事情，也没有什么前提条件，都是相同的过程，之前的文章我们都讨论过。</p><h3 id="第一步-配置存储池" tabindex="-1">第一步: 配置存储池 <a class="header-anchor" href="#第一步-配置存储池" aria-label="Permalink to “第一步: 配置存储池”">​</a></h3><p>Virsh命令行工具是一款管理virsh客户域的用户界面。virsh程序能在命令行中运行所给的命令以及它的参数。</p><p>本节中，我们要用它给我们的KVM环境创建存储池。想知道关于这个工具的更多信息，用以下这条命令。</p><pre><code># man virsh
</code></pre><p><strong>1. 用virsh带pool-define-as的命令来定义新的存储池，你需要指定名字、类型和类型参数。</strong></p><p>本例中，我们将名字取为Spool1，类型为目录。默认情况下你可以提供五个参数给该类型：</p><ul><li>source-host</li><li>source-path</li><li>source-dev</li><li>source-name</li><li>target</li></ul><p>对于目录类型，我们需要用最后一个参数“target”来指定存储池的路径，其它参数项我们可以用“-”来填充。</p><pre><code># virsh pool-define-as Spool1 dir - - - - &quot;/mnt/personal-data/SPool1/&quot;
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/02/Create-New-Storage-Pool.png" alt="Create New Storage Pool"></p><p><em>创建新存储池</em></p><p><strong>2. 查看环境中我们所有的存储池，用以下命令。</strong></p><pre><code># virsh pool-list --all
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/02/List-All-Storage-Pools.png" alt="List All Storage Pools"></p><p><em>列出所有存储池</em></p><p><strong>3. 现在我们来构造存储池了，用以下命令来构造我们刚才定义的存储池。</strong></p><pre><code># virsh pool-build Spool1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/02/Build-Storage-Pool.png" alt="Build Storage Pool"></p><p><em>构造存储池</em></p><p><strong>4. 用带pool-start参数的virsh命令来激活并启动我们刚才创建并构造完成的存储池。</strong></p><pre><code># virsh pool-start Spool1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/02/Active-Storage-Pool.png" alt="Active Storage Pool"></p><p><em>激活存储池</em></p><p><strong>5. 查看环境中存储池的状态，用以下命令。</strong></p><pre><code># virsh pool-list --all
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/02/Check-Storage-Pool-Status.png" alt="Check Storage Pool Status"></p><p><em>查看存储池状态</em></p><p>你会发现Spool1的状态变成了已激活。</p><p><strong>6. 对Spool1进行配置，让它每次都能被libvirtd服务自启动。</strong></p><pre><code># virsh pool-autostart Spool1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/02/Configure-Storage-Pool.png" alt="Configure KVM Storage Pool"></p><p><em>配置KVM存储池</em></p><p><strong>7. 最后来看看我们新的存储池的信息吧。</strong></p><pre><code># virsh pool-info Spool1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/02/Check-Storage-Pool-Information.png" alt="Check KVM Storage Pool Information"></p><p><em>查看KVM存储池信息</em></p><p>恭喜你，Spool1已经准备好待命，接下来我们试着创建存储卷来使用它。</p><h3 id="第二步-配置存储卷-磁盘映像" tabindex="-1">第二步: 配置存储卷/磁盘映像 <a class="header-anchor" href="#第二步-配置存储卷-磁盘映像" aria-label="Permalink to “第二步: 配置存储卷/磁盘映像”">​</a></h3><p>现在轮到磁盘映像了，用qemu-img命令在Spool1中创建一个新磁盘映像。获取更多细节信息，可以查看man手册。</p><pre><code># man qemu-img
</code></pre><p><strong>8. 我们应该在qemu-img命令之后指定“create, check,…”等等操作、磁盘映像格式、你想要创建的磁盘映像的路径和大小。</strong></p><pre><code># qemu-img create -f raw /mnt/personal-data/SPool1/SVol1.img 10G
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/02/Create-Storage-Volumes.png" alt="Create Storage Volume"></p><p><em>创建存储卷</em></p><p><strong>9. 通过使用带info的qemu-img命令，你可以获取到你的新磁盘映像的一些信息。</strong></p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/02/Check-Storage-Volume-Information.png" alt="Check Storage Volume Information"></p><p><em>查看存储卷信息</em></p><p><strong>警告</strong>: 不要用qemu-img命令来修改被运行中的虚拟机或任何其它进程所正在使用的映像，那样映像会被破坏。</p><p>现在是时候来创建虚拟机了。</p><h3 id="第三步-创建虚拟机" tabindex="-1">第三步: 创建虚拟机 <a class="header-anchor" href="#第三步-创建虚拟机" aria-label="Permalink to “第三步: 创建虚拟机”">​</a></h3><p><strong>10. 现在到最后一个环节了，在最后一步中，我们将用virt-install命令来创建虚拟机。virt-install是一个用来创建新的KVM虚拟机命令行工具，它使用“libvirt”管理程序库。想获取更多细节，同样可以查看man手册。</strong></p><pre><code># man virt-install
</code></pre><p>要创建新的KVM虚拟机，你需要用到带以下所有信息的命令。</p><ul><li><p>Name: 虚拟机的名字。</p></li><li><p>Disk Location: 磁盘映像的位置。</p></li><li><p>Graphics : 怎样连接VM，通常是SPICE。</p></li><li><p>vcpu : 虚拟CPU的数量。</p></li><li><p>ram : 以兆字节计算的已分配内存大小。</p></li><li><p>Location : 指定安装源路径。</p></li><li><p>Network : 指定虚拟网络，通常是virbr0网桥。</p><h1 id="virt-install-name-rhel7-disk-path-mnt-personal-data-spool1-svol1-img-graphics-spice-vcpu-1-ram-1024-location-run-media-dos-9e6f605a-f502-4e98-826e-e6376caea288-rhel-server-7-0-x86-64-dvd-iso-network-bridge-virbr0" tabindex="-1">virt-install --name=rhel7 --disk path=/mnt/personal-data/SPool1/SVol1.img --graphics spice --vcpu=1 --ram=1024 --location=/run/media/dos/9e6f605a-f502-4e98-826e-e6376caea288/rhel-server-7.0-x86_64-dvd.iso --network bridge=virbr0 <a class="header-anchor" href="#virt-install-name-rhel7-disk-path-mnt-personal-data-spool1-svol1-img-graphics-spice-vcpu-1-ram-1024-location-run-media-dos-9e6f605a-f502-4e98-826e-e6376caea288-rhel-server-7-0-x86-64-dvd-iso-network-bridge-virbr0" aria-label="Permalink to “virt-install --name=rhel7 --disk path=/mnt/personal-data/SPool1/SVol1.img --graphics spice --vcpu=1 --ram=1024 --location=/run/media/dos/9e6f605a-f502-4e98-826e-e6376caea288/rhel-server-7.0-x86_64-dvd.iso --network bridge=virbr0”">​</a></h1></li></ul><p><img src="http://www.tecmint.com/wp-content/uploads/2015/02/Create-New-Virtual-Machines.png" alt="Create New Virtual Machine"></p><p><em>创建新的虚拟机</em></p><p><strong>11. 你会看到弹出一个virt-vierwer窗口，像是在通过它在与虚拟机通信。</strong></p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/02/Booting-Virtual-Machine.jpeg" alt="Booting Virtual Machine"></p><p><em>虚拟机启动程式</em></p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/02/Installation-of-Virtual-Machine.jpeg" alt="Installation of Virtual Machine"></p><p><em>虚拟机安装过程</em></p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>以上就是我们KVM教程的最后一部分了，当然我们还没有完全覆盖到全部，我们只是打了个擦边球，所以现在该轮到你来好好地利用这些丰富的资源来做自己想做的事了。</p>`,66)),o("ul",null,[o("li",null,[i(n,{href:"https://access.redhat.com/site/documentation/en-US/Red_Hat_Enterprise_Linux/7/html/Virtualization_Getting_Started_Guide/index.html"},{default:a(()=>[...t[3]||(t[3]=[e("KVM Getting Started Guide",-1)])]),_:1})]),o("li",null,[i(n,{href:"https://access.redhat.com/site/documentation/en-US/Red_Hat_Enterprise_Linux/7/html/Virtualization_Deployment_and_Administration_Guide/index.html"},{default:a(()=>[...t[4]||(t[4]=[e("KVM Virtualization Deployment and Administration Guide",-1)])]),_:1})])]),t[20]||(t[20]=o("hr",null,null,-1)),o("p",null,[t[6]||(t[6]=e("via: ",-1)),i(n,{href:"http://www.tecmint.com/kvm-management-tools-to-manage-virtual-machines/"},{default:a(()=>[...t[5]||(t[5]=[e("http://www.tecmint.com/kvm-management-tools-to-manage-virtual-machines/",-1)])]),_:1})]),o("p",null,[t[10]||(t[10]=e("作者：",-1)),i(n,{href:"http://www.tecmint.com/author/dos2009/"},{default:a(()=>[...t[7]||(t[7]=[e("Mohammad Dosoukey",-1)])]),_:1}),t[11]||(t[11]=e(" 译者：",-1)),i(n,{href:"https://github.com/ZTinoZ"},{default:a(()=>[...t[8]||(t[8]=[e("ZTinoZ",-1)])]),_:1}),t[12]||(t[12]=e(" 校对：",-1)),i(n,{href:"https://github.com/wxy"},{default:a(()=>[...t[9]||(t[9]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[15]||(t[15]=e("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[13]||(t[13]=[e("LCTT",-1)])]),_:1}),t[16]||(t[16]=e(" 原创翻译，",-1)),i(n,{href:"http://linux.cn/"},{default:a(()=>[...t[14]||(t[14]=[e("Linux中国",-1)])]),_:1}),t[17]||(t[17]=e(" 荣誉推出",-1))])])}const x=r(d,[["render",u]]);export{S as __pageData,x as default};
